    "id": "noah-s-japan-korea-czechia-summer-adventure-part-4",
    "subject": "Noah’s Japan-Korea-Czechia Summer Adventure (Part 4)",
    "date": "2026-07-11T14:17:12.000Z",
    "fromName": "Noah Lee",
    "fromAddress": "noahdlee519@gmail.com",
    "to": "me",
    "folder": "inbox",
